// Original V3 effect configuration: UseGrayFuse=false, SoftLightAlpha=0, final degree=1.
// APP slider ranges/defaults are independent choices; original UI stored-float normalization is unresolved.
export const nativeTeethSpecs=Object.freeze([
 {key:'nativeTeethEnabled',label:'应用原牙齿美白',min:0,max:1,step:1,default:0,group:'teeth'},
 {key:'nativeTeethMaster',label:'总强度',min:0,max:100,step:1,default:100,group:'teeth'},
 {key:'nativeTeethWhiten',label:'祛黄',min:0,max:100,step:1,default:50,group:'teeth'},
 {key:'nativeTeethBright',label:'明度',min:0,max:100,step:1,default:50,group:'teeth'}
]);

export const toothMaskCombineVertex="attribute vec3 a_position;\nattribute vec2 a_texcoord;\n\nuniform mat4 u_mvpMatrix;\nuniform mat3 u_mvpMaskMatrix;\n\nvarying vec2 v_mask_texcoord;\n\nvoid main()\n{\n\tv_mask_texcoord = (u_mvpMaskMatrix * vec3(a_texcoord,1.0)).xy;\n\tgl_Position = u_mvpMatrix * vec4(a_position,1.0);\n}";

export const toothMaskCombineFragment="#ifdef GL_ES//for discriminate GLES & GL\n#ifdef GL_FRAGMENT_PRECISION_HIGH\nprecision highp float;\n#else\nprecision mediump float;\n#endif\n#else\n#define highp\n#define mediump\n#define lowp\n#endif\n\nuniform sampler2D s_mask;\nuniform float u_whiten;\nuniform float u_bright;\n\nvarying vec2 v_mask_texcoord;\n\nvoid main()\n{\n    float tooth = texture2D(s_mask,v_mask_texcoord).g;\n    gl_FragColor = vec4(u_whiten*tooth,tooth*u_bright,0.0,1.0);\n}\n";

export const whitenTeethV3Vertex="attribute vec2 a_position;\nattribute vec2 a_texcoord;\nvarying vec2 v_texcoordOut;\nuniform mat4 u_mvpMatrix;\n\nvoid main()\n{\n\tv_texcoordOut = a_texcoord;\n\tgl_Position = u_mvpMatrix * vec4(a_position,0.0,1.0);\n}\n";

export const whitenTeethV3Fragment="#ifdef GL_ES//for discriminate GLES & GL\n#ifdef GL_FRAGMENT_PRECISION_HIGH\nprecision highp float;\n#else\nprecision mediump float;\n#endif\n#else\n#define highp\n#define mediump\n#define lowp\n#endif\n\nuniform sampler2D s_src_texture;\nuniform sampler2D s_mask_texture;\nuniform sampler2D s_whiten_texture;\nuniform sampler2D s_bright_texture;\n\nvarying highp vec2 v_texcoordOut;\n\nuniform float u_softlight_alpha;\nuniform float u_degree;\n\n\n// \u57fa\u4e8e512 * 512\u7684\u57fa\u51c6\u56fe\nvec3 Lut3D(vec3 textureColor, sampler2D s_LutTex,float degree)\n{\n   float blueColor = textureColor.b * 63.0;\n   vec2 quad1;\n   quad1.y = floor(floor(blueColor) / 8.0);\n   quad1.x = floor(blueColor) - (quad1.y * 8.0);\n   vec2 quad2;\n   quad2.y = floor(ceil(blueColor) / 8.0);\n   quad2.x = ceil(blueColor) - (quad2.y * 8.0);\n   vec2 texPos1;\n   texPos1.x = (quad1.x * 0.125) + 0.0009765625 + ((0.125 - 0.001953125) * textureColor.r);\n   texPos1.y = (quad1.y * 0.125) + 0.0009765625 + ((0.125 - 0.001953125) * textureColor.g);\n   vec2 texPos2;\n   texPos2.x = (quad2.x * 0.125) + 0.0009765625 + ((0.125 - 0.001953125) * textureColor.r);\n   texPos2.y = (quad2.y * 0.125) + 0.0009765625 + ((0.125 - 0.001953125) * textureColor.g);\n   vec4 newColor1 = texture2D(s_LutTex, texPos1);\n   vec4 newColor2 = texture2D(s_LutTex, texPos2);\n   vec4 newColor = mix(newColor1, newColor2, fract(blueColor));\n   newColor.rgb = mix(textureColor,newColor.rgb,degree);\n   return newColor.rgb;\n}\n\n\nfloat SoflLight(float color_a, float color_b)\n{\n    if (color_b <= 0.5)\n    {\n        return (color_a * color_b) / 0.5 + color_a * color_a * (1.0 - 2.0 * color_b);\n    }\n    else\n    {\n        return (color_a * (1.0 - color_b)) / 0.5 + sqrt(color_a) * (2.0 * color_b - 1.0);\n    }\n}\n\nvoid main() \n{\n    vec4 origColor = texture2D(s_src_texture, v_texcoordOut);\n    vec3 src_color =origColor.rgb;\n    vec3 mask_color = texture2D(s_mask_texture, v_texcoordOut).rgb;\n    vec3 res_color = src_color;\n\n    float whiten_val = mask_color.r*u_degree;\n    float bright_val = mask_color.g*u_degree;\n    #if defined(USE_GRAY_FUSE)\n        float gray = dot(src_color.rgb, vec3(0.298912, 0.586611, 0.114478));\n        whiten_val = whiten_val*gray;\n        bright_val = bright_val*gray;\n    #endif\n\n    if (whiten_val > 0.001)\n    {\n        res_color = Lut3D(src_color, s_whiten_texture,whiten_val);\n    }\n    if (bright_val > 0.001)\n    {\n        res_color = Lut3D(res_color, s_bright_texture,bright_val);\n    }\n\n    // \u548c\u767d\u8272\u8fdb\u884c\u67d4\u5149\u53e0\u52a0\n    if (u_softlight_alpha > 0.0)\n    {\n        res_color.r = mix(res_color.r, SoflLight(res_color.r, 1.0), u_softlight_alpha);\n        res_color.g = mix(res_color.g, SoflLight(res_color.g, 1.0), u_softlight_alpha);\n        res_color.b = mix(res_color.b, SoflLight(res_color.b, 1.0), u_softlight_alpha);\n    }\n\n    gl_FragColor = vec4(res_color, origColor.a);\n}\n";

const whitenRaw="";

const brightRaw="";

let cached;export function getNativeTeethLUTs(){if(!cached)cached=Object.freeze({whiten:Uint8Array.from(atob(whitenRaw),c=>c.charCodeAt(0)),bright:Uint8Array.from(atob(brightRaw),c=>c.charCodeAt(0))});return cached;}
